import{_ as e,c as p,o as r,ah as h}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"萃","description":"高島易斷 - 萃","frontmatter":{"title":"萃","description":"高島易斷 - 萃"},"headers":[],"relativePath":"classics/takashima/045.md","filePath":"classics/takashima/045.md"}'),i={name:"classics/takashima/045.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="萃" tabindex="-1">萃 <a class="header-anchor" href="#萃" aria-label="Permalink to “萃”">​</a></h1><h2 id="萃-1" tabindex="-1">萃 <a class="header-anchor" href="#萃-1" aria-label="Permalink to “萃”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>萃：王假有廟，利見大人。亨，利貞。用大牲吉，利有攸往。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《萃》與《渙》名相反，而義則相須。《渙》之亨，取諸水流風行；《萃》之亨，取諸《兌》悅《坤》順。《渙》亦假廟，《渙》之假廟，見神氣之發揚；《萃》之假廟，見精誠之貫注：一散一聚，義各不同，而所以致誠者一也。王者合萬國之歡心，以事其祖考，侯助男衛，駿奔在廟，是《萃》之盛也。“大人”謂九五，五“萃有位”，能御眾以治亂，故“利見”。“亨，利貞”者，《兌》曰“亨，利貞”，《坤》曰“柔順利貞”，蓋即從《坤》《兌》來也。《坤》為牛，亦為用，故曰“用大牲”，言大人有嘉會，必殺牛而盟；既盟則可以往，故曰“利有攸往”。</p><h2 id="象辭" tabindex="-1">象辭 <a class="header-anchor" href="#象辭" aria-label="Permalink to “象辭”">​</a></h2><p>澤上於地，萃。君子以除戎器，戒不虞。</p><h2 id="象辭注" tabindex="-1">象辭注 <a class="header-anchor" href="#象辭注" aria-label="Permalink to “象辭注”">​</a></h2><p>《兌》為金，《坤》為器，有戎器之象。“除”，修治也，修治戎器，以防不虞，所謂有備無患也。卦象為澤上於地，水滿則溢，潰決奔突，勢莫能御，所當預為之防；水猶兵也，故可借鑑。按《穆天子傳》：有七《萃》之士，取宿衛環聚為名，是《萃》為防禦之士，所以遏亂也。《萃》象之“除戎器”，義蓋取此耳。</p><h2 id="占斷" tabindex="-1">占斷 <a class="header-anchor" href="#占斷" aria-label="Permalink to “占斷”">​</a></h2><p>○　問時運：氣運平順，但能安不忘危，自得歡樂無憂。</p><p>○　問戰徵：兵兇器，戰危事，惟能臨事而懼，好謀而成，可無意外之虞也。</p><p>○　問營商：《萃》有財聚之象，然聚必有散，盈必有虧，亦理之循環，所當時時預防。</p><p>○　問功名：宜由武功得名。</p><p>○　問婚姻：“匪寇婚媾”，《易》每以寇婚對言，蓋防兵禍，猶防女禍也。惟能預防，自可無咎。</p><p>○　問家宅：澤上於水，防有大水入屋之象。</p><p>○　問疾病：防胸腹有水脹之症，宜預為調治。</p><p>○　問行人：中途兵阻，一時難歸。</p><p>○　問六甲：生女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>《兌》為孚，故“有孚”；《坤》為終，初失位，故“不終”；《坤》為聚，亦為亂，故曰“乃亂乃萃”。初為《萃》之始，相孚猶淺，是以有初鮮終也；不得其終，則一念萃於此，易一念而萃於彼，其志先亂矣，是萃適以長亂也。《象傳》以“志亂”釋之，“乃”猶汝也，汝自萃之，汝自亂之也。初爻陰柔居下，雖得眾，未足以總之；初與四應，則御萃之權，當在四也。“若”，順也，“號”，令也，謂順從四之號令。“一握為笑”，謂推誠相與，眾皆歡悅，即《彖傳》所云“順以悅”也。上互《巽》，《巽》為號，下互《艮》，《艮》為執，執手，猶握手，退之所謂“握手出肺肝相示”者是也。《兌》為口，故曰“笑”，既得其笑，故“勿恤”。“往”，往四也，四能恩威並著，初自不致烏合為亂也，故“無咎”。</p><h2 id="初六佔" tabindex="-1">初六佔 <a class="header-anchor" href="#初六佔" aria-label="Permalink to “初六佔”">​</a></h2><p>○　問時運：運當初交，一順一逆，反覆無常，得所救援，可以無咎。</p><p>○　問功名：忽榮忽辱，由於中心無主也。</p><p>○　問營商：有初無終，聚散不定，不能獲利，僅可免咎而已。</p><p>○　問戰徵：統軍出征，防有兵變之憂。</p><p>○　問婚姻：有始亂之，而終娶之之象。</p><p>○　問疾病：此病忽號忽笑，由於心神昏亂，往而求醫，必無咎也。可勿憂。</p><p>○　問六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>明治十五年十月，大水陡發，上野高崎間鐵道所轄戶田川口假橋，致被沖塌。餘曾執司工事，往晤鐵道局長井上君，井上君曰：川口假橋衝裂，鐵道被梗，不得不急議修築。按川口堤岸，高出平地丈餘，若架造堅固鐵橋，工程既大，經費亦巨，若仍築假橋，一經發水，便遭沖決，亦非善策，若何而可？請為籌度。餘曰：不如問諸神易。乃筮得《萃》之《隨》。</p><p>斷曰：此卦澤上於地，明示洪水氾濫之象。佔得初爻，知此假橋建築不久，乍築乍傾，故謂之“有孚不終，乃亂乃萃”。初正應在四，宜聽令於四。“若號”者，四之號令也；“握”，猶執也。得四之號令，眾皆歡欣，願執其役，《兌》為悅，所謂“悅以勞民，民忘其勞”也，故曰“一握為笑”。但四不當位，則必橋之地位不當，五曰“萃有位”，則位宜從五。五變為《豫》，《豫》者有《豫》備之義，《豫》卦《震》上《坤》下，《萃》為《兌》上，《兌》西《震》東，易《兌》為《震》，橋宜改西從東方為當位。《坤》地在下，《坤》為厚，為基，宜從平地培土為基，營架一橋，再設鐵索，系鎖於兩堤，水來隨高，水落隨平，使無衝潰奔突之患，故得“無咎”。井上君聞之，亦以為然，眾議乃決，依此作橋。翌年水復大發，橋得無患，益嘆《易》象之神也。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>二居下卦之中，上應於五，知《萃》之當歸於五也。二與初、三為同體，初之“亂”，三之“嗟”，是失所《萃》也，二能引之，同《萃》於五，故曰“引吉，無咎”。上互《巽》，《巽》為繩，下互《艮》，《艮》為手，有引之象。“禴”，夏祭名，六二為《離》爻，《離》南方，為夏，故“利用禴”。二動體《困》，《困》二曰“利用享祀”，《萃》反為《升》，《升》二亦曰“利用禴”，以二得中，故其象同也。《彖》稱假廟用牲，二為助祭，助祭當獻方物，《坤》為吝嗇，故薄，然輸誠來《萃》，雖薄亦孚，孚，固不在多儀也。</p><h2 id="六二佔" tabindex="-1">六二佔 <a class="header-anchor" href="#六二佔" aria-label="Permalink to “六二佔”">​</a></h2><p>○　問時運：運得正中，吉。</p><p>○　問功名：可望汲引而進。</p><p>○　問營商：“引”，牽引也，想是合眾生意，必可獲吉，但須答願酬神。</p><p>○　問戰徵：古者出師必祭，於內曰類，於野曰馮是也，蓋祭神以誓師也。吉。</p><p>○　問婚姻：二應於五，是二五訂婚也，故曰“引吉”。</p><p>○　問疾病：仙人辟穀之法，曰引導，為引運其元氣，使之充實無虧，即可卻疾。</p><p>○　問六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>友人某來，請佔氣運，筮得《萃》之《困》。</p><p>斷曰：此卦地上有澤，可以蓄水，即可聚財，故卦曰《萃》。今佔得二爻，爻辭曰“引吉”，知足下所謀之事，必待有人引而伸之，乃可獲吉。二與五應，能為足下指引者，必屬於五。惜其中有三四兩爻間隔，宜備禮祈禱，以乞神祐，使三四不能阻礙，則所謀得遂，自然吉而無咎也。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>三處《坤》之上，《坤》為眾，得《萃》之象。蓋《萃》必眾心歡悅，其《萃》乃為可用，三以陰居陽，不能統率《坤》眾。《萃》者以利而《萃》，《萃》而無利，則《萃》者嗟矣，故曰“萃如嗟如”。卦以五爻為《萃》之宗主，即《彖》所稱“利見”之“大人”也，往而歸之，有攸利焉。“小吝”者，三無御《萃》之才，致騰眾口，為可鄙耳。《傳》曰“上巽也”，《萃》上互《巽》，《巽》五曰“無不利”，謂往而可得《巽》之利也。</p><h2 id="六三佔" tabindex="-1">六三佔 <a class="header-anchor" href="#六三佔" aria-label="Permalink to “六三佔”">​</a></h2><p>○　問時運：運途平平，無可獲利也。</p><p>○　問功名：功名不利，反被人鄙。</p><p>○　問營商：貨物雖多，不售可嗟，何所獲利？惟轉運他處，可得無咎。</p><p>○　問戰徵：有兵而不得其用，反致怨嗟，在主將無御眾之才也。</p><p>○　問婚姻：未免興怨偶之嗟。</p><p>○　問家宅：同居不睦，致多口舌，往遷可以無咎。</p><p>○　問疾病：胸膈積滯作痛，致聲聲叫苦，以兩便不利所致，利則可以無咎。</p><p>○　問訟事：不利。</p><p>○　問六甲：生女。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>友人來，請佔氣運，筮得《萃》之《鹹》。</p><p>斷曰：卦體上悅下順，眾人歸附，佔象得此，可為佳矣。今佔得第三爻，三爻以陰居陽，自無御眾之才，無以利眾，以致眾怨，故曰“萃如嗟如，無攸利”。知足下身任副局長，不得眾心，爻辭之言，若適為足下發也。足下當令其往附於局長，斯眾得其利，而可無咎矣。《象》曰“上巽”，巽順也，在足下運途亦順矣。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四出《坤》入《兌》，當內外卦之交，為多懼之地，初應之，三比之，開館招賓，禮賢下士，如漢之王莽曹操，臣而得眾，兇莫大焉。爻曰“大吉，無咎”，必其克盡“大吉”之道，乃得“無咎”；必其能立“無咎”之地，乃得“大吉”。若文王三分有二以服事殷，能有其萃，而不自以為萃，必率其萃而歸之於君，斯可謂大吉而無咎矣。《象傳》於“大吉，無咎”，而猶以“位不當”釋之，其旨嚴矣！</p><h2 id="九四佔" tabindex="-1">九四佔 <a class="header-anchor" href="#九四佔" aria-label="Permalink to “九四佔”">​</a></h2><p>○　問時運：氣運大好，無往不吉，但於地位不當，宜慎。</p><p>○　問功名：大吉，但恐德不稱位。</p><p>○　問營商：得財得利大吉；宜作退一步想，方能有始有終。</p><p>○　問戰徵：戰勝攻克，大吉大利；防功高震主，謗毀隨之。</p><p>○　問婚姻：四與初為正應，即為正配，吉；但門第恐不甚相當也。</p><p>○　問家宅：此宅人口興旺，家室平安，大吉；但地位少嫌卑下。</p><p>○　問疾病：是外強中乾之症，目下可保無咎。</p><p>○　問六甲：生女。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>某家支配人，請佔氣運，筮得《萃》之《比》。</p><p>斷曰：凡占卦取爻辭，亦當兼取爻象，往往有爻辭則吉，而爻象則兇者，亦有爻象則兇，而爻辭則吉者。今此爻之辭曰“大吉，無咎”，《象傳》曰“位不當”，未免於吉中有兇。足下佔氣運得此爻，在足下身任支配，凡主家之權利，皆歸足下擔負，一時趨附權利者，不必歸向於主家，必皆歸向於足下，此亦勢之所必然也。於是足下之名大震，足下之運大盛，安得不謂之“大吉”哉！其實此等權利，皆主家所有，非足下所可自有也，《象傳》以“位不當”戒之，足下最宜凜凜焉。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>五居尊位，為《萃》之主，故曰“萃有位”；居其位以御其眾，故“無咎”。然億兆之歸往在有位，亦不僅在有位也，要必有足以服眾者，而眾乃中心誠服矣。是《萃》以位，實《萃》以德，以德服人，此之謂“孚”，若徒曰“萃有位”而已，是以權位脅取，非心服也，孚何有焉？“非孚”而《萃》，後且有悔。“元永貞”者，《乾》《坤》之德也，“元”者，《乾》之“長人”，“永貞”者，《坤》之載物，既具此德，則德位兼備，群黎百姓，罔不相應，悔自亡矣。《象傳》曰“志未光”，為徒有其位言之耳。按：《比》《彖》亦曰“元永貞”，《比》以一陽統眾陰，故“元永貞”言於卦；《萃》雖有二陽而統眾陰者，以五為主，故“元永貞”言於五。義各有當也。</p><h2 id="九五佔" tabindex="-1">九五佔 <a class="header-anchor" href="#九五佔" aria-label="Permalink to “九五佔”">​</a></h2><p>○　問時運：得位得權，運當全盛，自可無咎。</p><p>○　問營商：財則聚矣，信尚未也，能守其正，業自可久。</p><p>○　問功名：位則高矣，望則隆矣，更宜修德履正。</p><p>○　問戰徵：三軍既集，大業可成，更宜推誠相與，可保永終。</p><p>○　問婚姻：位尊金多，可稱貴婿。</p><p>○　問家宅：此宅地位，山環水聚，聚族而居，吉。</p><p>○　問疾病：心神不定，宜靜養。</p><p>○　問訟事：以訟者爵位隆，聲勢盛，雖枉得直。</p><p>○　問六甲：生女。</p><p>○　問失物：久後可得，無咎。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>一日友人來，請佔氣運，筮得《萃》之《豫》。</p><p>斷曰：五爻為《萃》之主，既有其位，又有其眾，運無咎也。足下佔氣運，得此爻象，知足下非卑下之儔，有位有財，非一鄉之望，即一家之主也。特一時信義未孚，在眾人或懷疑慮，當履道守正，久而不失，斯言寡尤，行寡悔，而萬事亨通矣。</p><h2 id="上六解" tabindex="-1">上六解 <a class="header-anchor" href="#上六解" aria-label="Permalink to “上六解”">​</a></h2><p>“齎諮”，嗟嘆之辭。目出曰涕，鼻出曰洟，“齎諮涕洟”，悲泣之狀也。上爻陰柔不中，居《萃》之極，三與上為敵應，敵應則無《萃》，孤立於上而安得安乎？知其不安，則憂之深，慮之甚，極之“齎諮涕洟”，悲愁百結，人亦當諒其哀怨而來《萃》也，故得“無咎”。皖江陳氏以“諮”為資財，“齎”為持，謂財聚民散，是有其財而不能有其眾，則坐擁厚資，適以自危，如鹿臺巨橋，卒供興王之恩賞，此誠當痛哭流涕者也。其說亦親切。</p><h2 id="上六佔" tabindex="-1">上六佔 <a class="header-anchor" href="#上六佔" aria-label="Permalink to “上六佔”">​</a></h2><p>○　問時運：人必年老運退，極至窮極悲苦，為可憫也。然必有憐而救援者，得以無咎。</p><p>○　問營商：孤客無伴，途窮日暮，大可悲慮，幸而得救，無咎。</p><p>○　問功名：時衰運極，難望成名。</p><p>○　問戰徵：有軍眾叛離，主將孤立之象。</p><p>○　問婚姻：有生離死別之悲。</p><p>○　問家宅：仳離啜泣，家室不安。</p><p>○　問疾病：病自悲泣過甚而來，宜寬懷調養。</p><p>○　問六甲：生女。</p><h2 id="上六案例" tabindex="-1">上六案例 <a class="header-anchor" href="#上六案例" aria-label="Permalink to “上六案例”">​</a></h2><p>明治二十一年六月，餘為謀設攝綿土製造廠，遊寓愛知熱田，偶過熱田神宮，得晤神職某氏，相與講《易》。時際旱魃，鄉農數百，賽社祈雨，餘語神職某曰：鄉人誠求，神其諄諄然命之乎？神職曰：神何言哉！餘曰：神固不言，有足以通神之言者，其惟《易》乎？曷不筮之？筮得《萃》之《否》。</p><p>斷曰：此卦上卦之澤，為受水之地，澤出地上，有澤滿水溢之象。爻辭曰“齎諮”，在人為悲怨之情，在天為震怒之聲，即迅雷也；曰“涕洟”，在人為悲泣之狀，在天為滂沱之澤，即大雨也。當此迅雷大雨，洪水暴作，人民罹災，神亦為之不安，故《象》曰“未安上也”。計其時日，自初至上為六日，當必有驗。時七月十六日也，聞者多未之信。屆期天日晴朗，大宮司角田氏謂餘曰：大雨之期，佔在今日，恐不驗也。餘曰：餘惟就佔論佔，驗不驗非餘所知，然向來所佔，未有不驗也。至午後，雲湧風起，迄三時，雷公電母，風伯雨師，數駕齊來，頃刻之間，溝澮充盈，平地皆水，於是官司等，驚駭感服，過餘稱謝。翌年伊藤議長佐野顧問賽熱田神宮，向官司諸人詢問餘佔雨神驗，官司即以斷辭上申。兩公大感神德之靈應，詳詢熱田神社始祀之由，後宮內省發給祠幣十萬元，社格列伊勢大廟之次。</p>',105)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
